window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b322e242879a37dc"]={"versions": [{"id": "FIG-b322e242879a37dc", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Datenflussdiagramm im Kontext der AUTOSAR-Methodik (Classic Platform). Dargestellt ist der zentrale Schritt der ECU-Konfiguration (<code>Configure ECU</code>) mit den erforderlichen Eingangsartefakten und dem resultierenden Ausgangsartefakt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangsarfefakte (.XML):</strong></li>\n<li><code>Collection of Available Software Components</code>: Beschreibung der verfügbaren Software-Komponenten (SWC-Descriptions).</li>\n<li><code>ECU Extract of System Configuration : System</code>: Spezifischer Teilauszug der Systemkonfiguration für das betreffende Steuergerät.</li>\n<li><code>BSW-Module Description</code>: Modulbeschreibungen der Basis-Software (BSW-Moduldefinitionen/-beschreibungen).</li>\n<li><strong>Aktivität / Prozessschritt:</strong></li>\n<li><code>Configure ECU</code>: Konfigurationsaktivität (Chevron-/Pfeilsymbol), in der die BSW und RTE für das Steuergerät parametriert und konfiguriert werden.</li>\n<li><strong>Ausgangsartefakt (.XML):</strong></li>\n<li><code>ECU Configuration Description</code>: Vollständige Konfigurationsbeschreibung des Steuergeräts (EcucDescription).</li>\n<li><strong>Beziehungen:</strong></li>\n<li>Gerichtete Pfeile leiten von den drei XML-Eingabedokumenten auf die Aktivität <code>Configure ECU</code>.</li>\n<li>Ein gerichteter Pfeil führt von <code>Configure ECU</code> zum Zielartefakt <code>ECU Configuration Description</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Bereitstellung der XML-Eingabedateien: Auszug der Systemkonfiguration (ECU Extract), Komponentenbeschreibungen (Collection of Available Software Components) und BSW-Modulbeschreibungen (BSW-Module Description).</li>\n<li>Ausführung des Konfigurationsprozesses <code>Configure ECU</code> unter Zusammenführung und Auswertung dieser Beschreibungen.</li>\n<li>Erzeugung und Persistierung der <code>ECU Configuration Description</code> im XML-Format als Basis für die nachgelagerte Codegenerierung (BSW und RTE).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Abbildung definiert die minimal erforderlichen Input-Artefakte für den AUTOSAR-ECU-Konfigurationsschritt. Werkzeuge (ECU Configuration Editors / Tools) müssen in der Lage sein, Software-Component-Beschreibungen, den ECU Extract sowie BSW-Modulbeschreibungen semantisch konsistent zu verarbeiten und eine schemakonforme ECU Configuration Description bereitzustellen.</p>"}, {"id": "FIG-07019d4b7fa06982", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Datenflussdiagramm im Kontext der AUTOSAR-Methodik (Classic Platform). Dargestellt ist der zentrale Schritt der ECU-Konfiguration (<code>Configure ECU</code>) mit den erforderlichen Eingangsartefakten und dem resultierenden Ausgangsartefakt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangsarfefakte (.XML):</strong></li>\n<li><code>Collection of Available Software Components</code>: Beschreibung der verfügbaren Software-Komponenten (SWC-Descriptions).</li>\n<li><code>ECU Extract of System Configuration : System</code>: Spezifischer Teilauszug der Systemkonfiguration für das betreffende Steuergerät.</li>\n<li><code>BSW-Module Description</code>: Modulbeschreibungen der Basis-Software (BSW-Moduldefinitionen/-beschreibungen).</li>\n<li><strong>Aktivität / Prozessschritt:</strong></li>\n<li><code>Configure ECU</code>: Konfigurationsaktivität (Chevron-/Pfeilsymbol), in der die BSW und RTE für das Steuergerät parametriert und konfiguriert werden.</li>\n<li><strong>Ausgangsartefakt (.XML):</strong></li>\n<li><code>ECU Configuration Description</code>: Vollständige Konfigurationsbeschreibung des Steuergeräts (EcucDescription).</li>\n<li><strong>Beziehungen:</strong></li>\n<li>Gerichtete Pfeile leiten von den drei XML-Eingabedokumenten auf die Aktivität <code>Configure ECU</code>.</li>\n<li>Ein gerichteter Pfeil führt von <code>Configure ECU</code> zum Zielartefakt <code>ECU Configuration Description</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Bereitstellung der XML-Eingabedateien: Auszug der Systemkonfiguration (ECU Extract), Komponentenbeschreibungen (Collection of Available Software Components) und BSW-Modulbeschreibungen (BSW-Module Description).</li>\n<li>Ausführung des Konfigurationsprozesses <code>Configure ECU</code> unter Zusammenführung und Auswertung dieser Beschreibungen.</li>\n<li>Erzeugung und Persistierung der <code>ECU Configuration Description</code> im XML-Format als Basis für die nachgelagerte Codegenerierung (BSW und RTE).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Abbildung definiert die minimal erforderlichen Input-Artefakte für den AUTOSAR-ECU-Konfigurationsschritt. Werkzeuge (ECU Configuration Editors / Tools) müssen in der Lage sein, Software-Component-Beschreibungen, den ECU Extract sowie BSW-Modulbeschreibungen semantisch konsistent zu verarbeiten und eine schemakonforme ECU Configuration Description bereitzustellen.</p>"}], "trans": [{"from": "FIG-b322e242879a37dc", "to": "FIG-07019d4b7fa06982", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
